    """Direct O(n^4) check of the (LB) 4-point property (reference)."""
    n = len(ordering)
    for a in range(n):
        for b in range(a + 1, n):
            for c in range(b + 1, n):
                va, vb, vc = ordering[a], ordering[b], ordering[c]
                if adj[va][vc] and not adj[va][vb]:
                    ok = False
                    for d in range(a):
                        vd = ordering[d]
                        if adj[vd][vb] and not adj[vd][vc]:
                            ok = True
                            break
                    if not ok:
                        return False
    return True"}

